(function () {
const A = (title, summary, x = {}) => ({ title, summary, clauses: x.k || [], amendments: x.m || [], cases: x.c || [], questions: x.q || [], notes: x.notes || null, omitted: x.o });
const C = (name, cite, i, r, a, c) => ({ name, cite, i, r, a, c });
const Q = (type, q, outline) => ({ type, q, outline });
window.COI = window.COI || {}; window.COI.parts = window.COI.parts || {};
const R = (a, b) => { const o = []; for (let i = a; i <= b; i++) o.push(String(i)); return o; };

window.COI.parts['V'] = {
  key: 'V', part: 'V', title: 'The Union', range: 'Art. 52–151',
  intro: 'Part V sets up the Union executive (President, Vice-President, Council of Ministers, Attorney-General), Parliament and its procedure, the President\'s ordinance power, the Supreme Court and the Comptroller and Auditor-General. India follows the Westminster model: the President is the formal head and acts on ministerial advice under Article 74.',
  groups: [
    { slug: 'chi-the-president-and-vice-president', chapter: 'Chapter I · The Executive', name: 'The President and Vice-President', range: '52–73', ids: R(52, 73) },
    { slug: 'chi-council-of-ministers', name: 'Council of Ministers', range: '74–75', ids: ['74', '75'] },
    { slug: 'chi-the-attorney-general-for-india', name: 'The Attorney-General for India', range: '76', ids: ['76'] },
    { slug: 'chi-conduct-of-government-business', name: 'Conduct of Government Business', range: '77–78', ids: ['77', '78'] },
    { slug: 'chii-general', chapter: 'Chapter II · Parliament', name: 'General', range: '79–88', ids: R(79, 88) },
    { slug: 'chii-officers-of-parliament', name: 'Officers of Parliament', range: '89–98', ids: R(89, 98) },
    { slug: 'chii-conduct-of-business', name: 'Conduct of Business', range: '99–100', ids: ['99', '100'] },
    { slug: 'chii-disqualifications-of-members', name: 'Disqualifications of Members', range: '101–104', ids: R(101, 104) },
    { slug: 'chii-powers-privileges-and-immunities-of-parliament-and-its-members', name: 'Powers, Privileges and Immunities', range: '105–106', ids: ['105', '106'] },
    { slug: 'chii-legislative-procedure', name: 'Legislative Procedure', range: '107–111', ids: R(107, 111) },
    { slug: 'chii-procedure-in-financial-matters', name: 'Procedure in Financial Matters', range: '112–117', ids: R(112, 117) },
    { slug: 'chii-procedure-generally', name: 'Procedure Generally', range: '118–122', ids: R(118, 122) },
    { slug: 'chiii', chapter: 'Chapter III', name: 'Legislative Powers of the President', range: '123', ids: ['123'] },
    { slug: 'chiv', chapter: 'Chapter IV', name: 'The Union Judiciary', range: '124–147', ids: ['124', '124A', '124B', '124C', '125', '126', '127', '128', '129', '130', '131', '131A', '132', '133', '134', '134A', '135', '136', '137', '138', '139', '139A', '140', '141', '142', '143', '144', '144A', '145', '146', '147'] },
    { slug: 'chv', chapter: 'Chapter V', name: 'Comptroller and Auditor-General of India', range: '148–151', ids: R(148, 151) }
  ],
  articles: {
    '52': A('The President of India.', 'There shall be a President of India.', { k: ['Head of State; first citizen', 'Nominal executive under the parliamentary system'] }),
    '53': A('Executive power of the Union.', 'The executive power of the Union is vested in the President and shall be exercised by him directly or through subordinate officers in accordance with the Constitution. The supreme command of the Defence Forces vests in him, regulated by law.', {
      k: ['Executive power exercised on ministerial advice (Art. 74)', 'Supreme Commander of the armed forces', 'Parliament may confer functions on other authorities'],
      c: [C('Ram Jawaya Kapur v. State of Punjab', 'AIR 1955 SC 549', 'Can the executive carry on the business of publishing textbooks without legislation?', 'Executive power is what remains after legislative and judicial functions are taken away; it extends to matters on which the legislature can legislate, subject to fundamental rights. The President is a formal head; real power lies with the Council of Ministers.', 'No law authorised the business, but none prohibited it and no right was violated.', 'Executive action upheld.')],
      q: [Q('Essay', 'Discuss the constitutional position of the President of India.', ['Arts. 52, 53, 74', 'Westminster model; Ambedkar: "head of the State but not of the executive"', 'Ram Jawaya Kapur; U.N.R. Rao (1971); Shamsher Singh (1974)', '42nd and 44th Amendments to Art. 74', 'Discretion: choosing PM in hung House, returning advice once, pocket veto', 'Conclusion'])]
    }),
    '54': A('Election of President.', 'The President is elected by an electoral college of the elected members of both Houses of Parliament and the elected members of the Legislative Assemblies of the States, including Delhi and Puducherry.', { k: ['Nominated members and Legislative Council members do not vote', 'Delhi and Puducherry added by the 70th Amendment, 1992'], m: ['70th Amendment, 1992'] }),
    '55': A('Manner of election of President.', 'As far as practicable there shall be uniformity in the scale of representation of States and parity between the States as a whole and the Union. The election is by proportional representation by means of the single transferable vote, and voting is by secret ballot.', {
      k: ['Value of MLA vote = State population (1971 census) ÷ elected MLAs ÷ 1000', 'Value of MP vote = total value of all MLA votes ÷ elected MPs', '84th Amendment, 2002: 1971 census freeze till first census after 2026'],
      m: ['42nd Amendment, 1976 and 84th Amendment, 2002: population freeze']
    }),
    '56': A('Term of office of President.', 'The President holds office for five years from entering office, but may resign by writing to the Vice-President, may be removed by impeachment, and continues until the successor enters office.', {}),
    '57': A('Eligibility for re-election.', 'A person who holds or has held the office of President is eligible for re-election.', { k: ['No limit; only Dr. Rajendra Prasad served two terms'] }),
    '58': A('Qualifications for election as President.', 'A candidate must be a citizen of India, have completed 35 years of age, and be qualified for election as a member of the Lok Sabha. He must not hold an office of profit under the Government of India, a State Government or a local authority; the offices of President, Vice-President, Governor and Minister are excluded.', {}),
    '59': A('Conditions of President\'s office.', 'The President shall not be a member of either House of Parliament or a State Legislature and shall not hold any other office of profit. He is entitled to an official residence and to emoluments determined by Parliament, which shall not be diminished during his term.', {}),
    '60': A('Oath or affirmation by the President.', 'Before entering office, the President takes an oath before the Chief Justice of India to faithfully execute the office, to preserve, protect and defend the Constitution and the law, and to devote himself to the service and well-being of the people.', {}),
    '61': A('Procedure for impeachment of the President.', 'The President may be impeached for violation of the Constitution. The charge may be preferred by either House by a resolution moved after 14 days\' notice signed by at least one-fourth of its total members, and passed by at least two-thirds of the total membership. The other House investigates; if it also passes the resolution by two-thirds of its total membership, the President is removed from the date of passing.', {
      k: ['Only ground: violation of the Constitution (undefined)', 'Nominated members participate; State Legislatures do not', 'President may appear and be represented at the investigation', 'Quasi-judicial; no President has been impeached'],
      q: [Q('Short note', 'Impeachment of the President.', ['Ground', 'Procedure: notice, 1/4 signatures, 2/3 total membership in each House', 'Comparison with removal of judges (Art. 124(4))'])]
    }),
    '62': A('Time of holding election to fill vacancy in the office of President and the term of office of person elected to fill casual vacancy.', 'An election to fill a vacancy caused by expiry of term must be completed before the term ends. A vacancy caused by death, resignation, removal or otherwise must be filled within six months, and the person elected holds office for a full five-year term.', {}),
    '63': A('The Vice-President of India.', 'There shall be a Vice-President of India.', {}),
    '64': A('The Vice-President to be ex officio Chairman of the Council of States.', 'The Vice-President is ex officio Chairman of the Rajya Sabha and holds no other office of profit. While acting as President he does not perform the duties of Chairman or receive the Chairman\'s salary.', {}),
    '65': A('The Vice-President to act as President or to discharge his functions during casual vacancies in the office, or during the absence, of President.', 'On a vacancy in the office of President by death, resignation, removal or otherwise, the Vice-President acts as President until a new President enters office. When the President is unable to discharge functions owing to absence or illness, the Vice-President discharges them.', {}),
    '66': A('Election of Vice-President.', 'The Vice-President is elected by an electoral college of all members of both Houses of Parliament (elected and nominated), by proportional representation by single transferable vote and secret ballot. He must be a citizen, aged at least 35, qualified for election to the Rajya Sabha, and must not hold an office of profit.', { k: ['State Legislatures do not participate', 'Nominated MPs vote (unlike in the presidential election)'], m: ['11th Amendment, 1961: joint meeting replaced by electoral college'] }),
    '67': A('Term of office of Vice-President.', 'Five years. The Vice-President may resign by writing to the President and may be removed by a resolution of the Rajya Sabha passed by a majority of all its then members and agreed to by the Lok Sabha, after at least 14 days\' notice.', { k: ['Removal needs effective majority in Rajya Sabha and simple majority in Lok Sabha', 'No ground specified'] }),
    '68': A('Time of holding election to fill vacancy in the office of Vice-President and the term of office of person elected to fill casual vacancy.', 'An election on expiry of term must be completed before the term ends. A vacancy for any other reason shall be filled as soon as possible, and the person elected holds office for a full five years.', {}),
    '69': A('Oath or affirmation by the Vice-President.', 'The Vice-President takes an oath before the President, or a person appointed by him, to bear true faith and allegiance to the Constitution and faithfully discharge the duties of office.', {}),
    '70': A('Discharge of President\'s functions in other contingencies.', 'Parliament may make provision for the discharge of the President\'s functions in contingencies not provided for in the Constitution.', { k: ['President (Discharge of Functions) Act, 1969: the Chief Justice of India, failing whom the senior-most judge, acts if both offices are vacant'] }),
    '71': A('Matters relating to, or connected with, the election of a President or Vice-President.', 'All doubts and disputes arising out of the election of a President or Vice-President are inquired into and decided by the Supreme Court, whose decision is final. Acts done before the election is declared void are not invalidated. The election cannot be challenged on the ground of any vacancy in the electoral college.', {
      k: ['Exclusive original jurisdiction of the Supreme Court', 'Presidential and Vice-Presidential Elections Act, 1952'],
      m: ['39th Amendment, 1975 had excluded court jurisdiction; restored by 44th Amendment, 1978']
    }),
    '72': A('Power of President to grant pardons, etc., and to suspend, remit or commute sentences in certain cases.', 'The President may grant pardons, reprieves, respites or remissions of punishment, or suspend, remit or commute the sentence of any person convicted of an offence: where the sentence is by a court martial; where the offence is against a law on a matter to which the executive power of the Union extends; and in all cases of death sentence.', {
      k: ['Pardon: absolves sentence and conviction', 'Commutation: substitutes lighter punishment', 'Remission: reduces period without changing character', 'Respite: lesser sentence for special reasons (e.g. pregnancy)', 'Reprieve: temporary stay, usually of death sentence', 'Exercised on advice of the Council of Ministers; compare Governor under Art. 161 (no court martial power; but may pardon death sentences under s.433A CrPC context per Perarivalan)'],
      c: [
        C('Kehar Singh v. Union of India', '(1989) 1 SCC 204', 'Is the President bound to hear the petitioner orally, and is the exercise of Article 72 reviewable?', 'No right to oral hearing; the President can examine evidence afresh. Exercise of the power is subject to limited judicial review.', 'Petition by an Indira Gandhi assassination convict.', 'Petition dismissed; limited review recognised.'),
        C('Epuru Sudhakar v. Government of A.P.', '(2006) 8 SCC 161', 'On what grounds can a pardon be reviewed?', 'Review lies where the order was passed without application of mind, mala fide, on extraneous or irrelevant considerations, ignoring relevant material, or arbitrarily.', 'Governor remitted the sentence of a party worker for political reasons.', 'Remission quashed.'),
        C('Shatrughan Chauhan v. Union of India', '(2014) 3 SCC 1', 'Does unexplained delay in deciding mercy petitions entitle a death-row convict to commutation?', 'Inordinate and unexplained delay is a supervening circumstance violating Article 21 and is a ground for commutation; solitary confinement before rejection of mercy is illegal.', '15 convicts waited years for decisions.', 'Death sentences commuted; guidelines laid down.')
      ],
      q: [
        Q('Essay', 'Discuss the pardoning power of the President and Governor and the scope of judicial review.', ['Arts. 72 and 161 compared', 'Forms of clemency', 'Maru Ram (1981): exercised on advice', 'Kehar Singh; Epuru Sudhakar', 'Shatrughan Chauhan: delay', 'A.G. Perarivalan (2022): Governor bound by advice; delay'])
      ]
    }),
    '73': A('Extent of executive power of the Union.', 'The executive power of the Union extends to matters on which Parliament has power to make laws, and to rights, authority and jurisdiction exercisable by the Government of India under any treaty or agreement. It does not extend to matters on which State Legislatures also have power to make laws, unless expressly provided.', { k: ['Executive power is co-extensive with legislative power', 'Concurrent List: executive power generally remains with States'] }),
    '74': A('Council of Ministers to aid and advise President.', 'There shall be a Council of Ministers with the Prime Minister at the head to aid and advise the President, who shall act in accordance with such advice. The President may require the Council to reconsider the advice once, and shall act on the advice tendered after reconsideration. Whether and what advice was tendered shall not be inquired into in any court.', {
      k: ['"Shall act in accordance with such advice": 42nd Amendment, 1976', 'Proviso allowing one reconsideration: 44th Amendment, 1978', '74(2): advice not justiciable, but the material on which it is based may be examined (S.R. Bommai)'],
      m: ['42nd Amendment, 1976', '44th Amendment, 1978'],
      c: [
        C('U.N.R. Rao v. Indira Gandhi', '(1971) 2 SCC 63', 'Does the Council of Ministers cease to exist on dissolution of the Lok Sabha?', 'There must always be a Council of Ministers; the President cannot exercise executive power without its aid and advice.', 'Lok Sabha dissolved in December 1970.', 'Ministry continued validly.'),
        C('Shamsher Singh v. State of Punjab', '(1974) 2 SCC 831', 'Must the President or Governor personally satisfy himself before terminating a probationer judge?', 'The President and Governor exercise their powers on the advice of ministers, save in a few well-known exceptional situations; "satisfaction" is the satisfaction of the Council of Ministers.', 'Termination order signed on advice.', 'Cabinet system confirmed (7-judge bench).')
      ],
      q: [Q('Short note', 'Article 74 and the binding nature of ministerial advice.', ['Text before and after 1976 and 1978', 'Shamsher Singh', 'Art. 74(2) and S.R. Bommai'])]
    }),
    '75': A('Other provisions as to Ministers.', 'The Prime Minister is appointed by the President, and other Ministers on the PM\'s advice. The total number of Ministers, including the PM, shall not exceed 15% of the Lok Sabha\'s total membership. A member disqualified under the Tenth Schedule cannot be appointed a Minister until re-elected. Ministers hold office during the President\'s pleasure and are collectively responsible to the Lok Sabha. A non-member Minister must become a member within six months.', {
      k: ['75(1A) 15% cap and 75(1B): 91st Amendment, 2003', '75(3) collective responsibility to Lok Sabha', '75(5) six-month rule'],
      m: ['91st Amendment, 2003'],
      c: [
        C('S.P. Anand v. H.D. Deve Gowda', '(1996) 6 SCC 734', 'Can a person who is not a member of Parliament be appointed Prime Minister?', 'Article 75(5) applies to the PM as well; a non-member may be appointed for six months.', 'Deve Gowda was not an MP when appointed.', 'Appointment valid.'),
        C('S.R. Chaudhuri v. State of Punjab', '(2001) 7 SCC 126', 'Can a non-member be reappointed Minister repeatedly without being elected?', 'Reappointment of a non-member during the same legislature without election is a fraud on the Constitution.', 'Minister reappointed after six months lapsed.', 'Reappointment invalid.')
      ],
      q: [Q('Short note', 'Collective responsibility.', ['Art. 75(3)', 'No-confidence motion', 'Common Cause v. Union (1999)'])]
    }),
    '76': A('Attorney-General for India.', 'The President appoints a person qualified to be a Supreme Court judge as Attorney-General. He advises the Government on legal matters referred to him, performs other legal duties assigned, and has right of audience in all courts in India. He holds office during the President\'s pleasure.', { k: ['Highest law officer; not a member of the Cabinet', 'Right to speak in Parliament without vote (Art. 88)', 'Term not fixed'] }),
    '77': A('Conduct of business of the Government of India.', 'All executive action of the Government of India shall be expressed to be taken in the name of the President. Orders shall be authenticated as specified in rules. The President shall make rules for convenient transaction of business and allocation among Ministers.', { k: ['Government of India (Allocation of Business) Rules, 1961 and Transaction of Business Rules', 'Non-compliance with form does not invalidate an order if it is in fact a government decision'] }),
    '78': A('Duties of Prime Minister as respects the furnishing of information to the President, etc.', 'The Prime Minister shall communicate to the President all decisions of the Council of Ministers on administration and proposals for legislation, furnish information the President calls for, and, if the President requires, submit for the Council\'s consideration any matter decided by a Minister alone.', { k: ['President\'s right to be informed and to advise'] }),

    '79': A('Constitution of Parliament.', 'Parliament consists of the President and two Houses: the Council of States (Rajya Sabha) and the House of the People (Lok Sabha).', { k: ['President is an integral part of Parliament though not a member'] }),
    '80': A('Composition of the Council of States.', 'The Rajya Sabha consists of 12 members nominated by the President for special knowledge in literature, science, art and social service, and not more than 238 representatives of States and Union territories, elected by State Assembly members by proportional representation through single transferable vote.', {
      k: ['Maximum 250; present strength 245', 'Seats allocated in the Fourth Schedule'],
      c: [C('Kuldip Nayar v. Union of India', '(2006) 7 SCC 1', 'Were the removal of the domicile requirement and open ballot for Rajya Sabha elections valid?', 'Residence is not a constitutional requirement for representing a State; open ballot curbs cross-voting and does not violate free elections.', 'Representation of the People (Amendment) Act, 2003.', 'Amendments upheld.')]
    }),
    '81': A('Composition of the House of the People.', 'The Lok Sabha consists of not more than 530 members directly elected from territorial constituencies in the States and not more than 20 from Union territories. Seats are allocated so that the ratio of seats to population is as far as practicable the same for all States (except small States).', { k: ['Population figures frozen at the 1971 census until the first census after 2026 (84th Amendment, 2002)', 'Anglo-Indian nomination (Art. 331) lapsed in 2020 (104th Amendment)'], m: ['31st Amendment, 1973', '42nd and 84th Amendments: freeze', '87th Amendment, 2003: 2001 census for delimitation within States'] }),
    '82': A('Readjustment after each census.', 'After each census, the allocation of seats to States and division of States into constituencies shall be readjusted by an authority and in a manner determined by Parliament, without affecting the existing House until it is dissolved.', { k: ['Delimitation Commission Acts', 'Inter-State allocation frozen till after 2026'] }),
    '83': A('Duration of Houses of Parliament.', 'The Rajya Sabha is not subject to dissolution; one-third of its members retire every second year. The Lok Sabha continues for five years from its first meeting unless dissolved sooner; during a Proclamation of Emergency, Parliament may extend it by law for up to one year at a time, and not beyond six months after the Proclamation ceases.', { m: ['42nd Amendment, 1976 raised term to six years', '44th Amendment, 1978 restored five years'] }),
    '84': A('Qualification for membership of Parliament.', 'A person must be a citizen of India and make an oath before an Election Commission-authorised person; must be at least 30 years for the Rajya Sabha and 25 for the Lok Sabha; and possess other qualifications prescribed by Parliament.', {}),
    '85': A('Sessions of Parliament, prorogation and dissolution.', 'The President shall summon each House to meet at such time and place as he thinks fit, and six months shall not intervene between the last sitting of one session and the first sitting of the next. The President may prorogue either House and dissolve the Lok Sabha.', { k: ['Maximum six-month gap', 'Dissolution on PM\'s advice; discretion in rare cases where the PM has lost majority'] }),
    '86': A('Right of President to address and send messages to Houses.', 'The President may address either House or both Houses assembled together, and may send messages to either House about a pending Bill or otherwise; the House shall consider them with all convenient dispatch.', {}),
    '87': A('Special address by the President.', 'At the commencement of the first session after each general election and of the first session of each year, the President shall address both Houses assembled together and inform Parliament of the causes of its summons.', { k: ['Motion of Thanks; defeat signals loss of confidence'] }),
    '88': A('Rights of Ministers and Attorney-General as respects Houses.', 'Every Minister and the Attorney-General may speak in and take part in the proceedings of either House, joint sittings and committees of which they are named members, but are not entitled to vote by virtue of this Article.', {}),
    '89': A('The Chairman and Deputy Chairman of the Council of States.', 'The Vice-President is ex officio Chairman of the Rajya Sabha. The Rajya Sabha chooses one of its members as Deputy Chairman.', {}),
    '90': A('Vacation and resignation of, and removal from, the office of Deputy Chairman.', 'The Deputy Chairman vacates office on ceasing to be a member, may resign by writing to the Chairman, and may be removed by a resolution passed by a majority of all the then members after 14 days\' notice.', {}),
    '91': A('Power of the Deputy Chairman or other person to perform the duties of the office of, or to act as, Chairman.', 'When the Chairman\'s office is vacant or the Vice-President is acting as President, the Deputy Chairman performs the duties, or failing him a member appointed by the President. During the Chairman\'s absence from a sitting, the Deputy Chairman or a person determined by the rules presides.', {}),
    '92': A('The Chairman or the Deputy Chairman not to preside while a resolution for his removal from office is under consideration.', 'The Chairman or Deputy Chairman shall not preside while a resolution for his removal is being considered, though he may speak and take part. The Chairman cannot vote on such a resolution; the Deputy Chairman can vote in the first instance but not on equality of votes.', {}),
    '93': A('The Speaker and Deputy Speaker of the House of the People.', 'The Lok Sabha shall, as soon as may be, choose two of its members as Speaker and Deputy Speaker, and fill vacancies as they arise.', { k: ['Office of Deputy Speaker vacant through the 17th Lok Sabha (2019–24)'] }),
    '94': A('Vacation and resignation of, and removal from, the offices of Speaker and Deputy Speaker.', 'The Speaker or Deputy Speaker vacates office on ceasing to be a member, may resign, and may be removed by a resolution passed by a majority of all the then members after 14 days\' notice. On dissolution the Speaker continues until the first meeting of the new House.', {}),
    '95': A('Power of the Deputy Speaker or other person to perform the duties of the office of, or to act as, Speaker.', 'When the Speaker\'s office is vacant, the Deputy Speaker performs the duties, or failing him a member appointed by the President. During the Speaker\'s absence, the Deputy Speaker or a person determined by the rules acts as Speaker.', {}),
    '96': A('The Speaker or the Deputy Speaker not to preside while a resolution for his removal from office is under consideration.', 'The Speaker or Deputy Speaker shall not preside while a resolution for his removal is under consideration. The Speaker may speak and vote in the first instance on such a resolution, but not on equality of votes.', {}),
    '97': A('Salaries and allowances of the Chairman and Deputy Chairman and the Speaker and Deputy Speaker.', 'Their salaries and allowances are fixed by Parliament by law, and charged on the Consolidated Fund of India.', {}),
    '98': A('Secretariat of Parliament.', 'Each House shall have a separate secretarial staff. Parliament may regulate recruitment and service conditions; until then the President may make rules after consulting the Speaker or Chairman.', {}),
    '99': A('Oath or affirmation by members.', 'Every member of either House shall, before taking his seat, make an oath or affirmation before the President or a person appointed by him, in the form set out in the Third Schedule.', {}),
    '100': A('Voting in Houses, power of Houses to act notwithstanding vacancies and quorum.', 'All questions shall be determined by a majority of members present and voting, other than the presiding officer, who has a casting vote in case of equality. Proceedings are valid despite vacancies or participation of unentitled persons. Quorum is one-tenth of the total members of the House.', { k: ['Casting vote of presiding officer', 'Quorum: 1/10'] }),
    '101': A('Vacation of seats.', 'No person can be a member of both Houses, or of Parliament and a State Legislature. A member vacates his seat on disqualification, on resignation accepted by the presiding officer, or on absence without permission for 60 days.', { k: ['Resignation must be voluntary and genuine (33rd Amendment, 1974)'], m: ['33rd Amendment, 1974'] }),
    '102': A('Disqualifications for membership.', 'A person is disqualified for membership if he holds an office of profit under the Government of India or a State (other than an office exempted by Parliament), is of unsound mind declared by a court, is an undischarged insolvent, is not a citizen or has voluntarily acquired foreign citizenship, or is disqualified by law of Parliament. A person disqualified under the Tenth Schedule is also disqualified.', {
      k: ['Office of profit: appointment by Government, removal by Government, payment from public revenue, functions performed for Government, control by Government', 'Parliament (Prevention of Disqualification) Act, 1959', '102(2): Tenth Schedule (52nd Amendment, 1985)', 'Representation of the People Act, 1951 ss. 8–11'],
      m: ['52nd Amendment, 1985: clause (2)'],
      c: [
        C('Jaya Bachchan v. Union of India', '(2006) 5 SCC 266', 'Was the Chairperson of the U.P. Film Development Council holding an office of profit, though she drew no salary?', 'What matters is whether the office is capable of yielding a pecuniary gain, not whether it was actually received.', 'The office carried honorarium and perks.', 'Disqualified.'),
        C('Lily Thomas v. Union of India', '(2013) 7 SCC 653', 'Is s.8(4) RPA, giving sitting members three months\' protection after conviction, valid?', 'Parliament cannot make different disqualification rules for sitting members; disqualification takes effect on conviction.', 'Article 102(1)(e) does not allow deferral.', 'Section 8(4) struck down.')
      ],
      q: [Q('Short note', 'Office of profit.', ['Art. 102(1)(a)', 'Tests: Guru Gobinda Basu (1964), Shibu Soren (2001)', 'Jaya Bachchan', 'Prevention of Disqualification Act'])]
    }),
    '103': A('Decision on questions as to disqualifications of members.', 'If a question arises whether a member has become disqualified under Article 102(1), it shall be referred to the President, whose decision is final. Before deciding, he shall obtain the opinion of the Election Commission and act according to it.', { k: ['Does not cover Tenth Schedule disqualification (decided by the Speaker/Chairman)'], m: ['42nd Amendment, 1976; 44th Amendment, 1978'] }),
    '104': A('Penalty for sitting and voting before making oath or affirmation under article 99 or when not qualified or when disqualified.', 'A person who sits or votes as a member before taking the oath, or knowing that he is not qualified or is disqualified, is liable to a penalty of ₹500 for each day, recoverable as a debt due to the Union.', {}),
    '105': A('Powers, privileges, etc., of the Houses of Parliament and of the members and committees thereof.', 'There shall be freedom of speech in Parliament, subject to the Constitution and rules. No member is liable in any court for anything said or any vote given in Parliament or a committee, and no person is liable for publication by authority of a House. Other powers, privileges and immunities shall be as defined by Parliament by law, and until so defined, as they existed immediately before the 44th Amendment came into force.', {
      k: ['Not codified; earlier linked to the House of Commons (changed by 44th Amendment)', 'Collective privileges: punish for contempt, regulate internal affairs, exclude strangers', 'Individual privileges: freedom of speech, freedom from arrest in civil cases during session and 40 days before and after'],
      m: ['42nd Amendment, 1976; 44th Amendment, 1978'],
      c: [
        C('Pandit M.S.M. Sharma v. Sri Krishna Sinha (Searchlight case)', 'AIR 1959 SC 395', 'Does legislative privilege prevail over a journalist\'s freedom of speech under 19(1)(a)?', 'Privileges under Article 194(3) are as much part of the Constitution as Article 19(1)(a), and prevail over it; Article 21 is satisfied as the rules are procedure established by law.', 'Editor published expunged portions of a speech.', 'Privilege upheld.'),
        C('In re Keshav Singh (Special Reference No. 1 of 1964)', 'AIR 1965 SC 745', 'Can a court entertain a habeas corpus petition by a person committed for contempt by a legislature?', 'Legislatures do not have the House of Commons\' power to issue unspeaking warrants immune from review; courts can examine committals where fundamental rights are involved.', 'Conflict between U.P. Assembly and Allahabad High Court.', 'Judicial review of privilege exercise affirmed.'),
        C('P.V. Narasimha Rao v. State (CBI/SPE)', '(1998) 4 SCC 626', 'Are MPs who accepted bribes to vote against a no-confidence motion immune?', 'Majority held those who took bribes and voted were immune under Article 105(2).', 'JMM bribery case.', 'Overruled by Sita Soren v. Union of India (2024).'),
        C('Sita Soren v. Union of India', '2024 INSC 161', 'Does Article 105(2)/194(2) protect a legislator from prosecution for bribery?', 'Bribery is complete on acceptance and is not "in respect of" a speech or vote; privilege is not available (7-judge bench, unanimous).', 'Legislator accused of bribe for Rajya Sabha vote.', 'P.V. Narasimha Rao overruled.')
      ],
      q: [Q('Essay', 'Discuss parliamentary privileges and their relationship with fundamental rights.', ['Meaning and sources', 'Art. 105 clauses', 'Searchlight; Keshav Singh', 'Raja Ram Pal (2007): expulsion for cash-for-query; judicial review', 'P.V. Narasimha Rao to Sita Soren', 'Need for codification'])]
    }),
    '106': A('Salaries and allowances of members.', 'Members of either House receive salaries and allowances determined by Parliament by law.', { k: ['Salary, Allowances and Pension of Members of Parliament Act, 1954'] }),
    '107': A('Provisions as to introduction and passing of Bills.', 'Except Money Bills and other financial Bills, a Bill may originate in either House. It is not passed unless agreed to by both Houses with or without amendment. A Bill pending in Parliament does not lapse on prorogation. A Bill pending in the Rajya Sabha that has not been passed by the Lok Sabha does not lapse on dissolution of the Lok Sabha.', { k: ['On dissolution, Bills pending in the Lok Sabha or passed by it and pending in the Rajya Sabha lapse'] }),
    '108': A('Joint sitting of both Houses in certain cases.', 'If a Bill passed by one House is rejected by the other, the Houses disagree on amendments, or more than six months pass without the other House passing it, the President may summon a joint sitting. The Bill is passed by a majority of the total members of both Houses present and voting. Not available for Money Bills or Constitution Amendment Bills.', { k: ['Presided over by the Speaker', 'Used three times: Dowry Prohibition (1961), Banking Service Commission Repeal (1978), POTA (2002)'] }),
    '109': A('Special procedure in respect of Money Bills.', 'A Money Bill shall not be introduced in the Rajya Sabha. After passage by the Lok Sabha, the Rajya Sabha must return it within 14 days with recommendations, which the Lok Sabha may accept or reject. If not returned within 14 days, it is deemed passed by both Houses.', {}),
    '110': A('Definition of "Money Bills".', 'A Bill is a Money Bill if it contains only provisions dealing with: imposition, abolition, remission, alteration or regulation of any tax; borrowing by the Government of India; custody of the Consolidated or Contingency Fund; appropriation from the Consolidated Fund; declaring expenditure charged on it; receipt of money into public accounts; or matters incidental to these. The Speaker\'s certificate that a Bill is a Money Bill is final.', {
      k: ['"Only" is the key word', 'Speaker\'s certificate final under 110(3), but subject to judicial review (Rojer Mathew)'],
      c: [
        C('K.S. Puttaswamy (Aadhaar) v. Union of India', '(2019) 1 SCC 1', 'Was the Aadhaar Act validly passed as a Money Bill?', 'Majority held s.7 (benefits from the Consolidated Fund) was the core, so it qualified as a Money Bill; Chandrachud J. dissented, calling it a fraud on the Constitution.', 'Rajya Sabha was bypassed.', 'Upheld (4:1).'),
        C('Rojer Mathew v. South Indian Bank Ltd.', '(2020) 6 SCC 1', 'Is the Speaker\'s certification of a Money Bill immune from judicial review? Was the Finance Act, 2017 (tribunal changes) a valid Money Bill?', 'The Speaker\'s decision is open to judicial review; the Money Bill question was referred to a larger bench, doubting the Aadhaar majority.', 'Finance Act altered tribunal service conditions.', 'Referred to a 7-judge bench (pending).')
      ],
      q: [Q('Short note', 'Money Bill and the role of the Speaker.', ['Art. 110 matters', 'Art. 109 procedure', 'Aadhaar; Rojer Mathew'])]
    }),
    '111': A('Assent to Bills.', 'When a Bill has been passed by both Houses, the President shall declare that he assents or withholds assent. Except for a Money Bill, he may return it with a message requesting reconsideration; if the Houses pass it again with or without amendment, he shall not withhold assent.', { k: ['Absolute veto (withholding)', 'Suspensive veto (return once)', 'Pocket veto: no time limit (Zail Singh and the Indian Post Office (Amendment) Bill, 1986)', 'Constitutional Amendment Bills: must assent (Art. 368(2), 24th Amendment)'] }),
    '112': A('Annual financial statement.', 'The President shall cause to be laid before both Houses for every financial year a statement of the estimated receipts and expenditure of the Government of India (the Budget), distinguishing expenditure charged on the Consolidated Fund from other expenditure and revenue from other expenditure.', { k: ['Charged expenditure includes President\'s emoluments, salaries of the Chairman, Speaker, Supreme Court judges, CAG, debt charges, decrees'] }),
    '113': A('Procedure in Parliament with respect to estimates.', 'Charged expenditure is not submitted to the vote of Parliament but may be discussed. Other estimates are submitted as demands for grants to the Lok Sabha, which may assent, refuse or reduce them. No demand shall be made except on the President\'s recommendation.', { k: ['Cut motions: policy cut, economy cut, token cut'] }),
    '114': A('Appropriation Bills.', 'After grants are made, a Bill is introduced to appropriate from the Consolidated Fund the money needed for grants and charged expenditure. No amendment may vary the amount or destination of grants. No money shall be withdrawn from the Consolidated Fund except under appropriation made by law.', {}),
    '115': A('Supplementary, additional or excess grants.', 'The President shall cause supplementary estimates to be laid where authorised amounts prove insufficient or a need for new expenditure arises, and present a demand for any excess spent beyond the grant.', {}),
    '116': A('Votes on account, votes of credit and exceptional grants.', 'The Lok Sabha may make a grant in advance for part of the year pending completion of the budget procedure (vote on account), grant a vote of credit for unexpected demands, and make an exceptional grant not part of current service.', {}),
    '117': A('Special provisions as to financial Bills.', 'A Bill making provision for matters in Article 110(1)(a)–(f) shall be introduced only on the President\'s recommendation and not in the Rajya Sabha. A Bill which, if enacted, would involve expenditure from the Consolidated Fund shall not be passed unless the President has recommended consideration.', {}),
    '118': A('Rules of procedure.', 'Each House may make rules regulating its procedure and conduct of business. The President, after consulting the Chairman and Speaker, may make rules for joint sittings and communications between the Houses.', {}),
    '119': A('Regulation by law of procedure in Parliament in relation to financial business.', 'Parliament may by law regulate procedure and conduct of business on financial matters, and such law prevails over rules made under Article 118.', {}),
    '120': A('Language to be used in Parliament.', 'Business in Parliament shall be transacted in Hindi or English. The presiding officer may permit a member who cannot adequately express himself in either to address the House in his mother tongue.', {}),
    '121': A('Restriction on discussion in Parliament.', 'No discussion shall take place in Parliament on the conduct of any judge of the Supreme Court or a High Court in the discharge of his duties, except on a motion for his removal.', {}),
    '122': A('Courts not to inquire into proceedings of Parliament.', 'The validity of any proceedings in Parliament shall not be called in question on the ground of any alleged irregularity of procedure. Officers and members empowered to regulate procedure are not subject to the jurisdiction of any court in that respect.', {
      k: ['Protects procedural irregularity, not illegality or unconstitutionality'],
      c: [C('Raja Ram Pal v. Hon\'ble Speaker, Lok Sabha', '(2007) 3 SCC 184', 'Is the expulsion of MPs (cash-for-query) beyond judicial review?', 'Article 122 bars review of mere procedural irregularity, not substantive illegality, unconstitutionality or violation of fundamental rights.', 'Eleven MPs expelled.', 'Expulsion upheld, but scope of judicial review affirmed.')]
    }),
    '123': A('Power of President to promulgate Ordinances during recess of Parliament.', 'When both Houses are not in session and the President is satisfied that circumstances exist requiring immediate action, he may promulgate an Ordinance having the same force as an Act of Parliament. It must be laid before both Houses and ceases six weeks after Parliament reassembles, or earlier if disapproved by resolutions. It may be withdrawn at any time and is void if it makes a provision Parliament could not enact.', {
      k: ['Maximum life: six months + six weeks', 'Exercised on ministerial advice', '38th Amendment made satisfaction non-justiciable; removed by 44th Amendment'],
      m: ['38th Amendment, 1975; 44th Amendment, 1978'],
      c: [
        C('R.C. Cooper v. Union of India', '(1970) 1 SCC 248', 'Is the President\'s satisfaction under Article 123 justiciable?', 'Left open, but satisfaction may be challenged for mala fides.', 'Banking Companies Ordinance, 1969.', 'Led to the 38th Amendment.'),
        C('D.C. Wadhwa v. State of Bihar', '(1987) 1 SCC 378', 'Is repeated re-promulgation of ordinances valid?', 'Re-promulgation without placing ordinances before the legislature is a fraud on the Constitution.', 'Bihar re-promulgated 256 ordinances, some for 14 years.', 'Practice struck down.'),
        C('Krishna Kumar Singh v. State of Bihar', '(2017) 3 SCC 1', 'Is the satisfaction justiciable, and are rights created under a lapsed ordinance permanent?', 'Satisfaction is subject to judicial review; failure to lay an ordinance before the legislature is a constitutional violation; re-promulgation is a fraud on the Constitution; lapse does not automatically preserve rights created.', 'Bihar ordinances on taking over Sanskrit schools.', 'Ordinances held invalid (7-judge bench).')
      ],
      q: [Q('Essay', 'Discuss the ordinance-making power of the President and Governor with reference to judicial review.', ['Arts. 123 and 213', 'Conditions and duration', 'A.K. Roy (1982)', 'R.C. Cooper; T. Venkata Reddy (1985)', 'D.C. Wadhwa; Krishna Kumar Singh', 'Conclusion: emergency power, not parallel legislation'])]
    }),
    '124': A('Establishment and constitution of the Supreme Court.', 'There shall be a Supreme Court consisting of the Chief Justice of India and other judges (now 33 plus the CJI by statute). Judges are appointed by the President and hold office until 65. A judge may resign or be removed by order of the President after an address by each House, supported by a majority of total membership and two-thirds of members present and voting, on the ground of proved misbehaviour or incapacity. Qualifications: citizen and five years as a High Court judge, ten years as an advocate of a High Court, or a distinguished jurist in the President\'s opinion.', {
      k: ['Supreme Court (Number of Judges) Amendment Act, 2019: 33 + CJI', 'Judges (Inquiry) Act, 1968', 'Collegium system: CJI and four senior-most judges'],
      m: ['99th Amendment, 2014 (NJAC) struck down in 2015'],
      c: [
        C('S.P. Gupta v. Union of India (First Judges case)', '1981 Supp SCC 87', 'Does "consultation" with the CJI mean concurrence?', 'Consultation does not mean concurrence; the executive has primacy.', 'Challenge to transfers and non-extension of additional judges.', 'Executive primacy upheld.'),
        C('Supreme Court Advocates-on-Record Association v. Union of India (Second Judges case)', '(1993) 4 SCC 441', 'Who has primacy in appointments?', 'The CJI\'s opinion, formed with two senior-most judges, has primacy; S.P. Gupta overruled.', '9-judge bench.', 'Collegium created.'),
        C('In re Special Reference No. 1 of 1998 (Third Judges case)', '(1998) 7 SCC 739', 'What is the composition of the collegium?', 'For Supreme Court appointments, the CJI consults four senior-most judges.', 'Presidential reference under Art. 143.', 'Five-member collegium.'),
        C('Supreme Court Advocates-on-Record Association v. Union of India (Fourth Judges / NJAC case)', '(2016) 5 SCC 1', 'Are the 99th Amendment and the NJAC Act valid?', 'Primacy of the judiciary in appointments is part of independence of the judiciary, a basic feature; the NJAC, with two eminent persons and the Law Minister able to veto, violated it.', 'Decided 16 October 2015 (4:1).', 'NJAC struck down; collegium restored.')
      ],
      q: [Q('Essay', 'Trace the evolution of the law on appointment of judges in India.', ['Arts. 124 and 217', 'Judges cases I–III', 'NJAC case', 'Memorandum of Procedure', 'Removal: Justice V. Ramaswami (1993); Sub-Committee on Judicial Accountability (1991)', 'Independence of judiciary as basic structure'])]
    }),
    '124A': A('National Judicial Appointments Commission.', 'Provided for an NJAC of the CJI (Chairperson), two senior-most judges, the Union Law Minister and two eminent persons to recommend appointments of judges.', { o: 'Inserted by the 99th Amendment, 2014; struck down in Supreme Court Advocates-on-Record Association v. Union of India (2015).', m: ['99th Amendment, 2014'] }),
    '124B': A('Functions of Commission.', 'Gave the NJAC the duty to recommend appointment of the CJI, Supreme Court judges, Chief Justices and judges of High Courts, and transfers.', { o: 'Inserted by the 99th Amendment, 2014; struck down in 2015.' }),
    '124C': A('Power of Parliament to make law.', 'Empowered Parliament to regulate the NJAC\'s procedure for appointment by law.', { o: 'Inserted by the 99th Amendment, 2014; struck down in 2015.' }),
    '125': A('Salaries, etc., of Judges.', 'Judges are paid salaries determined by Parliament by law (originally in the Second Schedule). Their privileges, allowances, leave and pension shall not be varied to their disadvantage after appointment.', { m: ['54th Amendment, 1986'] }),
    '126': A('Appointment of acting Chief Justice.', 'When the office of CJI is vacant or the CJI is unable to perform duties, the President appoints one of the other judges to perform them.', {}),
    '127': A('Appointment of ad hoc Judges.', 'If there is no quorum of permanent judges, the CJI may, with the President\'s consent and after consulting the Chief Justice of the High Court concerned, request a High Court judge qualified for appointment to the Supreme Court to attend as an ad hoc judge.', {}),
    '128': A('Attendance of retired Judges at sittings of the Supreme Court.', 'The CJI may, with the President\'s consent, request a retired judge of the Supreme Court (or a retired High Court judge qualified for the Supreme Court) to sit and act as a judge.', {}),
    '129': A('Supreme Court to be a court of record.', 'The Supreme Court is a court of record and has all the powers of such a court, including the power to punish for contempt of itself.', {
      k: ['Records have evidentiary value', 'Contempt power is inherent; Contempt of Courts Act, 1971 does not limit it'],
      c: [
        C('In re Vinay Chandra Mishra', '(1995) 2 SCC 584', 'Can the Supreme Court suspend an advocate\'s licence while punishing contempt?', 'Contempt power under Article 129 is inherent; but suspending a licence is for the Bar Council (corrected in Supreme Court Bar Association v. Union, 1998).', 'Senior advocate insulted a High Court judge.', 'Convicted for contempt.'),
        C('In re Prashant Bhushan', '(2021) 1 SCC 745', 'Did tweets criticising the CJI and the Court amount to criminal contempt?', 'Scandalising the court by scurrilous attacks undermining public confidence is contempt; fair criticism is not.', 'Two tweets in 2020.', 'Convicted; fined ₹1.')
      ]
    }),
    '130': A('Seat of Supreme Court.', 'The Supreme Court sits in Delhi or such other place as the CJI, with the President\'s approval, appoints.', {}),
    '131': A('Original jurisdiction of the Supreme Court.', 'The Supreme Court has exclusive original jurisdiction in disputes between the Government of India and one or more States; between the Government of India and States on one side and other States on the other; and between two or more States, so far as the dispute involves a question on which a legal right depends. It excludes disputes arising from pre-Constitution treaties and agreements.', {
      k: ['Only federal disputes; private parties excluded', 'Inter-State water disputes excluded by Art. 262'],
      c: [
        C('State of Rajasthan v. Union of India', '(1977) 3 SCC 592', 'Could States challenge the Home Minister\'s letter asking them to dissolve Assemblies?', 'A dispute must involve a legal right of the State; on merits, the Court would not interfere with a proposed Article 356 action.', 'Nine States sued after the 1977 elections.', 'Suits dismissed.'),
        C('State of Karnataka v. Union of India', '(1977) 4 SCC 608', 'Can a State challenge a Commission of Inquiry against its Chief Minister under Article 131?', 'A State can sue to protect its constitutional rights; the Commissions of Inquiry Act applied validly.', 'Commission set up against Devaraj Urs.', 'Suit maintainable but dismissed on merits.')
      ]
    }),
    '131A': A('Exclusive jurisdiction of the Supreme Court in regard to questions as to constitutional validity of Central laws. [Omitted]', 'Gave the Supreme Court exclusive jurisdiction to decide the validity of Central laws.', { o: 'Inserted by the 42nd Amendment, 1976; omitted by the 43rd Amendment, 1977.' }),
    '132': A('Appellate jurisdiction of Supreme Court in appeals from High Courts in certain cases.', 'An appeal lies to the Supreme Court from any judgment, decree or final order of a High Court, in civil, criminal or other proceedings, if the High Court certifies under Article 134A that the case involves a substantial question of law as to the interpretation of the Constitution.', {}),
    '133': A('Appellate jurisdiction of Supreme Court in appeals from High Courts in regard to civil matters.', 'An appeal lies in civil proceedings if the High Court certifies that the case involves a substantial question of law of general importance that needs to be decided by the Supreme Court.', { m: ['30th Amendment, 1972: removed valuation test (₹20,000)'] }),
    '134': A('Appellate jurisdiction of Supreme Court in regard to criminal matters.', 'An appeal lies from a High Court in criminal proceedings if the High Court has on appeal reversed an acquittal and sentenced the accused to death, withdrawn a case from a subordinate court, tried it and sentenced the accused to death, or certifies the case as fit for appeal.', { k: ['Supreme Court (Enlargement of Criminal Appellate Jurisdiction) Act, 1970: life or 10+ years on reversal of acquittal'] }),
    '134A': A('Certificate for appeal to the Supreme Court.', 'A High Court shall, on its own motion or on oral application by an aggrieved party immediately after judgment, determine whether to grant a certificate under Article 132, 133 or 134.', { m: ['44th Amendment, 1978'] }),
    '135': A('Jurisdiction and powers of the Federal Court under existing law to be exercisable by the Supreme Court.', 'Until Parliament provides otherwise, the Supreme Court exercises the jurisdiction and powers of the Federal Court under existing law, where Articles 133 and 134 do not apply.', {}),
    '136': A('Special leave to appeal by the Supreme Court.', 'The Supreme Court may, in its discretion, grant special leave to appeal from any judgment, decree, determination, sentence or order in any cause or matter passed by any court or tribunal in India, except a court or tribunal under laws relating to the armed forces.', {
      k: ['Widest, discretionary jurisdiction; no right of appeal', 'Exercised sparingly where grave injustice or substantial question arises'],
      c: [
        C('Pritam Singh v. The State', 'AIR 1950 SC 169', 'On what principles will special leave in criminal cases be granted?', 'Only in exceptional and special circumstances, where substantial and grave injustice has been done.', 'Early case laying down approach.', 'Leave standard set.'),
        C('Kunhayammed v. State of Kerala', '(2000) 6 SCC 359', 'Does dismissal of an SLP by a non-speaking order merge the High Court order in the Supreme Court\'s?', 'Doctrine of merger does not apply to dismissal of an SLP at the leave stage; it is not a declaration of law under Article 141.', 'Review sought in High Court after SLP dismissal.', 'High Court review maintainable.')
      ],
      q: [Q('Short note', 'Special leave petition.', ['Art. 136 scope', 'Discretion', 'Exclusion of armed forces tribunals', 'Kunhayammed'])]
    }),
    '137': A('Review of judgments or orders by the Supreme Court.', 'Subject to Parliament\'s law and rules under Article 145, the Supreme Court may review any judgment or order it has pronounced.', {
      k: ['Grounds as in Order XLVII CPC: error apparent, new evidence, other sufficient reason', 'Curative petition beyond review: Rupa Ashok Hurra v. Ashok Hurra (2002) 4 SCC 388'],
      c: [C('Rupa Ashok Hurra v. Ashok Hurra', '(2002) 4 SCC 388', 'Can a final judgment be reopened after review is dismissed?', 'A curative petition lies to prevent abuse of process or gross miscarriage of justice, such as breach of natural justice or bias, certified by a senior advocate.', '5-judge bench.', 'Curative petition created.')]
    }),
    '138': A('Enlargement of the jurisdiction of the Supreme Court.', 'Parliament may confer further jurisdiction on the Supreme Court on Union List matters, and the Government of India and a State may by special agreement confer jurisdiction on any matter if Parliament so provides.', {}),
    '139': A('Conferment on the Supreme Court of powers to issue certain writs.', 'Parliament may by law confer on the Supreme Court power to issue writs for purposes other than enforcing fundamental rights.', {}),
    '139A': A('Transfer of certain cases.', 'The Supreme Court may withdraw and decide cases involving the same substantial question of law pending before it and one or more High Courts, or before two or more High Courts. It may also transfer any case from one High Court to another in the interests of justice.', { m: ['42nd Amendment, 1976; 44th Amendment, 1978'] }),
    '140': A('Ancillary powers of Supreme Court.', 'Parliament may confer supplemental powers on the Supreme Court not inconsistent with the Constitution, to enable it to exercise its jurisdiction more effectively.', {}),
    '141': A('Law declared by Supreme Court to be binding on all courts.', 'The law declared by the Supreme Court shall be binding on all courts within the territory of India.', {
      k: ['Ratio decidendi binds; obiter of the Supreme Court is also generally followed', 'The Supreme Court itself is not bound by its decisions', 'Larger bench decisions bind smaller benches (Central Board of Dawoodi Bohra Community v. State of Maharashtra, 2005)'],
      c: [
        C('Bengal Immunity Co. v. State of Bihar', 'AIR 1955 SC 661', 'Is the Supreme Court bound by its own previous decisions?', 'Article 141 does not bind the Supreme Court itself; it may depart from earlier decisions when convinced of error.', 'Overruled State of Bombay v. United Motors (1953).', 'Self-overruling power recognised.'),
        C('Golak Nath v. State of Punjab', 'AIR 1967 SC 1643', 'Can the Court overrule prospectively?', 'Doctrine of prospective overruling applied under Articles 32, 141 and 142.', 'Overruled Sajjan Singh.', 'Prospective overruling adopted.')
      ],
      q: [Q('Short note', 'Doctrine of precedent under Article 141.', ['Binding effect', 'Ratio vs obiter', 'Bengal Immunity', 'Per incuriam; prospective overruling (Golak Nath)'])]
    }),
    '142': A('Enforcement of decrees and orders of Supreme Court and orders as to discovery, etc.', 'The Supreme Court may pass any decree or order necessary for doing complete justice in any cause or matter pending before it, enforceable throughout India. It has powers to secure attendance of persons, discovery or production of documents, and investigation or punishment of contempt.', {
      k: ['"Complete justice": plenary, residuary power', 'Cannot be used to ignore substantive statutory provisions (Supreme Court Bar Association, 1998)'],
      c: [
        C('Union Carbide Corporation v. Union of India', '(1991) 4 SCC 584', 'Could the Court approve a settlement quashing criminal proceedings in the Bhopal case?', 'Article 142 power is not limited by statutory provisions on withdrawal of prosecutions where complete justice requires.', 'US$470 million settlement.', 'Settlement upheld; criminal quashing later reversed in review.'),
        C('Supreme Court Bar Association v. Union of India', '(1998) 4 SCC 409', 'Can Article 142 be used to suspend an advocate\'s licence?', 'Article 142 cannot supplant substantive law; licence suspension lies with the Bar Council under the Advocates Act.', 'In re Vinay Chandra Mishra.', 'That part of Mishra overruled.'),
        C('Shilpa Sailesh v. Varun Sreenivasan', '2023 INSC 468', 'Can the Supreme Court grant divorce on irretrievable breakdown of marriage under Article 142?', 'Yes, to do complete justice, including dispensing with the six-month waiting period under s.13B HMA, subject to fundamental public policy.', '5-judge bench.', 'Power recognised with guidelines.')
      ]
    }),
    '143': A('Power of President to consult Supreme Court.', 'If a question of law or fact of public importance has arisen or is likely to arise, the President may refer it to the Supreme Court for its opinion, and the Court may report its opinion after hearing. Disputes under the proviso to Article 131 (pre-Constitution treaties) may also be referred, and the Court shall report its opinion.', {
      k: ['Advisory jurisdiction; opinion not binding on the President', 'Court may decline under 143(1) (Ismail Faruqui, 1994)'],
      c: [
        C('In re Delhi Laws Act', 'AIR 1951 SC 332', 'Limits of delegated legislation.', 'Legislature cannot delegate essential legislative functions.', 'First reference.', 'Opinion given.'),
        C('Dr. M. Ismail Faruqui v. Union of India', '(1994) 6 SCC 360', 'Should the Court answer whether a temple existed before the Babri Masjid?', 'The Court may decline to answer a reference that is superfluous or raises questions it cannot appropriately answer.', 'Reference under 143(1) on Ayodhya.', 'Reference declined.'),
        C('In re Assent, Withholding or Reservation of Bills by the Governor and President', '2025 INSC 1333', 'Can courts impose time limits on the Governor and President for assent to Bills?', 'Courts cannot impose fixed timelines on the Governor (Art. 200) or President (Art. 201) for assent, and "deemed assent" is alien to the Constitution; but prolonged, unexplained inaction is open to limited judicial review. The President need not seek the Court\'s opinion on every reserved Bill.', 'The reference followed State of Tamil Nadu v. Governor of Tamil Nadu (8 April 2025), where a 2-judge bench set timelines and declared deemed assent for 10 Bills under Art. 142.', 'Opinion delivered on 20 November 2025 by a 5-judge bench led by CJI B.R. Gavai; the April 2025 timelines and deemed assent were disapproved.')
      ]
    }),
    '144': A('Civil and judicial authorities to act in aid of the Supreme Court.', 'All authorities, civil and judicial, in the territory of India shall act in aid of the Supreme Court.', {}),
    '144A': A('Special provisions as to disposal of questions relating to constitutional validity of laws. [Omitted]', 'Required a minimum of seven judges and a two-thirds majority to declare a law unconstitutional.', { o: 'Inserted by the 42nd Amendment, 1976; omitted by the 43rd Amendment, 1977.' }),
    '145': A('Rules of Court, etc.', 'The Supreme Court may, with the President\'s approval, make rules regulating its practice and procedure. Cases involving a substantial question of law as to the interpretation of the Constitution, or references under Article 143, shall be heard by at least five judges.', { k: ['Constitution Bench minimum five judges (145(3))', 'Supreme Court Rules, 2013'] }),
    '146': A('Officers and servants and the expenses of the Supreme Court.', 'Appointments of officers and servants are made by the CJI or a judge or officer he directs. Administrative expenses, including salaries and pensions, are charged on the Consolidated Fund of India.', {}),
    '147': A('Interpretation.', 'References to substantial questions of law as to interpretation of the Constitution include questions on interpretation of the Government of India Act, 1935, the Indian Independence Act, 1947, and Orders in Council made under them.', {}),
    '148': A('Comptroller and Auditor-General of India.', 'The CAG is appointed by the President and may be removed only in the manner and on the grounds of a Supreme Court judge. He is not eligible for further office under the Government after ceasing to hold office. His salary and conditions are determined by Parliament and not varied to his disadvantage; expenses of his office are charged on the Consolidated Fund.', { k: ['Term: six years or 65 years, whichever is earlier (CAG (DPC) Act, 1971)', 'Guardian of the public purse (Ambedkar)'] }),
    '149': A('Duties and powers of the Comptroller and Auditor-General.', 'The CAG performs duties and exercises powers in relation to the accounts of the Union, the States and other bodies as prescribed by Parliament by law.', {
      k: ['Comptroller and Auditor-General\'s (Duties, Powers and Conditions of Service) Act, 1971', 'Audits receipts, expenditure, government companies and bodies substantially financed by government'],
      c: [C('Arvind Gupta v. Union of India', '(2013) 1 SCC 393', 'Can the CAG\'s role in scrutinising decisions like spectrum and coal allocation be curtailed?', 'The CAG\'s audit includes efficiency and propriety; reports go to Parliament, which decides on them.', 'Challenge to CAG\'s 2G and coal reports.', 'CAG\'s role upheld.')]
    }),
    '150': A('Form of accounts of the Union and of the States.', 'The accounts of the Union and the States shall be kept in the form prescribed by the President on the advice of the CAG.', {}),
    '151': A('Audit reports.', 'The CAG\'s reports on the accounts of the Union shall be submitted to the President, who shall cause them to be laid before Parliament; reports on State accounts go to the Governor, to be laid before the State Legislature.', { k: ['Examined by the Public Accounts Committee'] })
  }
};
})();
